            if v == color and start is None:
                start = i
            elif v != color and start is not None:
                out.append((start, i - 1))
                start = None
        return out

    def paired(a, b):
        result = []
        for color in set(a) & set(b):
            if color == bg:
                continue
            for x in runs(a, color):
                for y in runs(b, color):
                    if x[1] - x[0] == y[1] - y[0]:
                        result.append((color, x, y))
        return result

    vertical = paired([g[r][0] for r in range(h)], [g[r][w-1] for r in range(h)])
    horizontal = paired([g[0][c] for c in range(w)], [g[h-1][c] for c in range(w)])
